def f(n):
    return n // 10 + 3 * (n % 10)

def find_cycle(n):
    path = []
    seen = {}
    while n not in seen:
        seen[n] = len(path)
        path.append(n)
        n = f(n)
    return path, seen, n, len(path) - seen[n]

# Let's test some numbers and see the cycles they enter.
for i in range(100):
    path, seen, n, cycle_len = find_cycle(i)
    if cycle_len > 0:
        print(f"Start {i} enters cycle {path[seen[n]:]} at index {seen[n]}")

